17	const VERT = /* glsl */ `
18	attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
19	attribute vec3 aTarget; attribute float aClustered;
20	uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim, uMorph;
21	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
22	const float TAU = 6.2831853;
23	void main() {
24	  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
25	  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
26	  float passed = step(d, uSweep);
27	  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
28	  vFlare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 14.0) * (1.0 - pow(uSweep, 12.0)) : 0.0;
29	  vRing = abs(aCp - uCp) < 0.5 ? 1.0 : 0.0;          // acquired by the current sweep
30	  vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
31	  vec3 pp = mix(position, aTarget, uMorph);            // page 2: comments fly into their cluster
32	  vec4 mv = modelViewMatrix * vec4(pp, 1.0);
33	  float depth = smoothstep(3.2, 7.5, -mv.z);           // far contacts recede
34	  vAlpha = vis * mix(uDim, 1.0, aSel) * mix(0.95, 0.4, depth) * mix(1.0, mix(0.08, 0.4, aClustered), uMorph);
35	  gl_Position = projectionMatrix * mv;
36	  gl_PointSize = aSize * uScale * (1.0 + vRing * 0.25 + vFlare * 2.0 + vHov * 2.2) / -mv.z;
37	}`;
38	const FRAG = /* glsl */ `
39	uniform vec3 uColor; uniform float uFade;
40	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
41	void main() {
42	  float r = length(gl_PointCoord - 0.5);
43	  if (r > 0.5) discard;
44	  float dot = smoothstep(0.5, 0.3, r);
45	  float ring = smoothstep(0.5, 0.42, r) * smoothstep(0.24, 0.32, r);
46	  float a = mix(dot, ring, vRing * (1.0 - vFlare));
47	  vec3 col = mix(uColor, vec3(1.0), max(vFlare, vHov));
48	  gl_FragColor = vec4(col, min(1.0, vAlpha + vHov) * a * uFade);
49	}`;
