81	const ORDER: LayerId[] = ["comment", "research", "study", "option", "sales"]; // inside out
82	const RISE = 0.85, FALL = 0.7, STAGGER = 0.07;                                 // seconds
83	const easeOutBack = (t: number) => 1 + 2.2 * Math.pow(t - 1, 3) + 1.2 * Math.pow(t - 1, 2);
84	const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
