87	// Focus choreography: the chosen layer springs up (slight overshoot) with a soft scale pulse; the others sink and
88	// fade in a ripple outward from it. Releasing focus ripples back the same way. Under reduced motion the layers still
89	// glide (the move is what shows which layer the item belongs to), just without overshoot, pulse or ripple.
90	function Layer({ id, focus, children }: { id: LayerId; focus: LayerId | null; children: ReactNode }) {
91	  const ref = useRef<THREE.Group>(null);
92	  const st = useRef({ y: 0, a: 1, fy: 0, fa: 1, t0: -1, delay: 0, rising: false, focus: null as LayerId | null });
93	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
94	  useFrame(({ clock }) => {
95	    const g = ref.current;
96	    if (!g) return;
97	    const s = st.current, now = clock.elapsedTime;
98	    if (s.focus !== focus) {                 // new target: start a tween from wherever the layer is now
99	      const anchor = focus ?? s.focus;       // ripple out from the layer gaining (or losing) focus
100	      s.focus = focus;
101	      s.fy = s.y; s.fa = s.a; s.t0 = now; s.rising = focus === id;
102	      s.delay = reduced || anchor == null || s.rising ? 0 : Math.abs(ORDER.indexOf(id) - ORDER.indexOf(anchor)) * STAGGER;
103	    }
104	    const [ty, ta] = focus == null ? [0, 1] : focus === id ? [LIFT, 1] : [SINK, FADE];
105	    let p = 1;
106	    if (s.t0 >= 0) p = Math.min(1, Math.max(0, (now - s.t0 - s.delay) / (s.rising ? RISE : FALL)));
107	    if (p >= 1 && s.y === ty && s.a === ta && g.userData.settled === children) return;
108	    s.y = s.fy + (ty - s.fy) * (s.rising && !reduced ? easeOutBack(p) : easeInOut(p));
109	    s.a = s.fa + (ta - s.fa) * easeOut(p);
110	    if (p >= 1) { s.y = ty; s.a = ta; }
111	    g.position.y = s.y;
112	    g.scale.setScalar(s.rising && !reduced ? 1 + 0.04 * Math.sin(Math.PI * p) : 1);
113	    g.userData.settled = children;
114	    g.traverse((o) => {
115	      const mat = (o as THREE.Mesh).material;
116	      if (!mat) return;
117	      for (const m of Array.isArray(mat) ? mat : [mat]) {
118	        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uFade) m.uniforms.uFade.value = s.a; continue; }
