482	function SweepBlade() {
483	  const mat = useMemo(() => new THREE.ShaderMaterial({
484	    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
485	    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
486	    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
487	  }), []);
488	  return (
489	    <>
490	      <mesh material={mat} position={[(R.sales + 0.1) / 2, 0, 0]}><planeGeometry args={[R.sales + 0.1, 1.4]} /></mesh>
491	      <mesh position={[(R.sales + 0.1) / 2, 0, 0]}><boxGeometry args={[R.sales + 0.1, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
492	    </>
493	  );
494	}
